{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울형 키즈카페 경계에서 20미터 떨어진 사유지가 일반 공중의 통행·이용에 제공되지 않는 경우, 키즈카페 주변 30미터 조항만으로 지정 대상에 포함되는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "해당 사유지는 서울형 키즈카페 시설의 경계선으로부터 30미터 이내에 있더라도, 조례 제5조제1항제5호는 ‘일반 공중의 통행·이용 등에 제공된 구역’만을 금연구역 지정 대상으로 정하고 있으므로, 일반 공중의 통행·이용에 제공되지 않는 사유지는 그 조항만으로 지정 대상에 포함되지 않는다.",
          "b_ids": "금연:제5조제1항제5호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
